head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > moveFooterColumn]<br/>Footer Column 의 ID 또는 인덱스값을 사용하여 Footer Column 의 위치를 이동합니다.",
    "validation" : [
        "Column 의 ID 는 고정값으로 항상 같은 Column 을 가리키지만, 인덱스값은 대상 Column 이 변경되므로 주의해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - Body 5컬럼 (col1~col5) 단일 헤더/바디 행, 동적 5컬럼 dataList 바인딩
//  - Footer MultiLine 2행 5컬럼 : 상단행 footer column id f1c1~f1c5, 하단행 id f2c1~f2c5
//  - columnMove 속성 미설정 (@spec2 : columnMove 와 무관하게 동작)
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // 그리드 구조 + 사용법 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="그리드는 Body 5컬럼 + Footer 2행 구성. par_fromInfo·par_toIndex 에서 Footer Column ID 선택 후 moveFooterColumn 실행. ID 는 고정값이라 항상 같은 Footer Column 을 가리킴. columnMove 속성과 무관하게 동작."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성 (5 Column, 5 Row)
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col5" name="col5" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [];
    for (let i = 1; i <= 5; i++) {
        jsonData.push({
            "col1" : "A" + i, "col2" : "B" + i, "col3" : "C" + i, "col4" : "D" + i, "col5" : "E" + i
        });
    }
    dlt_bind.setJSON(jsonData, false);

    let cList = $c.gcm.createCList({ dataList : "data:dlt_bind" });

    // target 생성 (Header 5컬럼 + gBody 5컬럼 + Footer MultiLine 2행 5컬럼)
    //  - Footer 상단행 column id f1c1~f1c5 (값 F1-col1~F1-col5)
    //  - Footer 하단행 column id f2c1~f2c5 (값 F2-col1~F2-col5)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:760px;height:280px;">';
    strTarget += '<w2:caption style="" id="caption1" value="moveFooterColumn 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="hcol1" value="col1"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="hcol2" value="col2"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="hcol3" value="col3"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="hcol4" value="col4"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol5" value="col5"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="col5" dataList="col5"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '<w2:footer style="" id="footer1">';
    // Footer 상단행 : f1c1~f1c5
    strTarget += '<w2:row style="" id="frow1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="f1c1" value="F1-col1"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="f1c2" value="F1-col2"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="f1c3" value="F1-col3"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="f1c4" value="F1-col4"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="f1c5" value="F1-col5"></w2:column>';
    strTarget += '</w2:row>';
    // Footer 하단행 : f2c1~f2c5
    strTarget += '<w2:row style="" id="frow2">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="f2c1" value="F2-col1"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="f2c2" value="F2-col2"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="f2c3" value="F2-col3"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="f2c4" value="F2-col4"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="f2c5" value="F2-col5"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 결과 출력 초기화 후 현재 Footer / Body 순서 출력
//  - Footer 상단행(F1) DOM 좌→우 순서 / Footer 하단행(F2) DOM 좌→우 순서
//  - Body 표시 순서 getColumnOrder(true) (읽기 전용, Body 불변 확인)
scwin.printOrder = function () {
    let bottom = wf_body_bottom.getObj("scwin");

    let footTable = document.querySelector("table[id*='target1_foot_table']");
    let rows = footTable ? footTable.querySelectorAll("tbody tr") : [];

    let f1 = [];
    let f2 = [];
    if (rows[0]) {
        rows[0].querySelectorAll("td").forEach(function (td) {
            let t = (td.textContent || '').trim();
            if (t) f1.push(t);
        });
    }
    if (rows[1]) {
        rows[1].querySelectorAll("td").forEach(function (td) {
            let t = (td.textContent || '').trim();
            if (t) f2.push(t);
        });
    }

    bottom.setReturnValue("[Footer 상단행(F1) 순서] " + JSON.stringify(f1));
    bottom.setReturnValue("[Footer 하단행(F2) 순서] " + JSON.stringify(f2));
    bottom.setReturnValue("[Body 표시 순서 ID] " + JSON.stringify(target1.getColumnOrder(true)));
}



// moveFooterColumn 실행 (ID 인자)
//  - fromInfo / toIndex 모두 Footer Column ID 문자열 (par_ getValue 그대로, parseInt 금지)
//  - ID 는 고정값으로 항상 같은 Footer Column 을 가리킴
scwin.btn_run_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let fromInfo = par_fromInfo.getValue();
    let toIndex = par_toIndex.getValue();

    bottom.setReturnValue("moveFooterColumn(fromInfo='" + fromInfo + "', toIndex='" + toIndex + "')");

    target1.moveFooterColumn(fromInfo, toIndex);

    scwin.printOrder();
}
